+
+/**
+ * Moves `qty` of a batch to location `to`. Moving all of it changes the
+ * batch's location; moving part splits it into a new batch at `to` with the
+ * same item, lot, expiry and received date, and writes a "transfer_out"
+ * movement on the old batch and a "transfer_in" movement on the new one.
+ * Returns { batch, moved }: the original batch and the batch now at `to`.
+ */
+export function transfer(store, batchId, to, qty, { at }) {
+  const batch = getBatch(store, batchId);
+  if (!store.data.locations.some((loc) => loc.id === to)) throw new AppError("unknown_location", { id: to });
+  if (!(qty > 0) || qty > batch.qty) throw new AppError("invalid_qty");
+  if (batch.location === to) throw new AppError("bad_request", { reason: `batch ${batch.id} is already at ${to}` });
+  if (qty === batch.qty) {
+    batch.location = to;
+    return { batch, moved: batch };
+  }
+  const moved = { ...batch, id: store.nextId("batch"), qty, location: to };
+  batch.qty = Math.round((batch.qty - qty) * 1000) / 1000;
+  store.data.batches.push(moved);
+  record(store, { type: "transfer_out", batchId: batch.id, qty, at, ref: `batch:${moved.id}` });
+  record(store, { type: "transfer_in", batchId: moved.id, qty, at, ref: `batch:${batch.id}` });
+  return { batch, moved };
+}
